// Generic Tree DP - two-state (selected / not selected)
// Returns [notSelected, selected] from each subtree
function treeDP(root) {
  let answer = 0;

  function dfs(node) {
    if (!node) return [0, 0]; // base: null node contributes nothing

    const [leftNo, leftYes] = dfs(node.left);
    const [rightNo, rightYes] = dfs(node.right);

    // if node NOT selected: children can be either
    const notSelected = Math.max(leftNo, leftYes) + Math.max(rightNo, rightYes);

    // if node IS selected: children must NOT be selected
    const selected = node.val + leftNo + rightNo;

    return [notSelected, selected];
  }

  const [no, yes] = dfs(root);
  return Math.max(no, yes);
}

// Tree Diameter - single-value state, global answer tracked externally
function diameterOfBinaryTree(root) {
  let maxDiameter = 0;

  function height(node) {
    if (!node) return 0;
    const leftH = height(node.left);
    const rightH = height(node.right);
    // diameter through this node: left path + right path
    maxDiameter = Math.max(maxDiameter, leftH + rightH);
    // return height of this subtree to parent
    return Math.max(leftH, rightH) + 1;
  }

  height(root);
  return maxDiameter;
}
